import{c as t,Q as o,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Claude Dynamic Workflows (not only) for PMs: The Ultimate Guide","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-08-@PawelHuryn-358857.md","filePath":"research/tweets/2026-06-08-@PawelHuryn-358857.md","lastUpdated":1785909234000}'),n={name:"research/tweets/2026-06-08-@PawelHuryn-358857.md"};function s(i,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="claude-dynamic-workflows-not-only-for-pms-the-ultimate-guide" tabindex="-1">Claude Dynamic Workflows (not only) for PMs: The Ultimate Guide <a class="header-anchor" href="#claude-dynamic-workflows-not-only-for-pms-the-ultimate-guide" aria-label="Permalink to &quot;Claude Dynamic Workflows (not only) for PMs: The Ultimate Guide&quot;">​</a></h1><p><strong>作者</strong>：Paweł Huryn (@PawelHuryn)<br><strong>發布時間</strong>：2026-06-08<br><strong>原始連結</strong>：<a href="https://x.com/pawelhuryn/status/2064079508689358857" target="_blank" rel="noreferrer">https://x.com/pawelhuryn/status/2064079508689358857</a><br><strong>類型</strong>：Twitter Article<br><strong>統計</strong>：❤️ 178 · 🔁 30 · 🔖 451 · 👁 78,134</p><hr><h2 id="分析摘要" tabindex="-1">分析摘要 <a class="header-anchor" href="#分析摘要" aria-label="Permalink to &quot;分析摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：113 agents / 1.95M tokens / 12 min 的 product discovery 案例展示 dynamic workflow；「Orchestrator 從 model 移到 code，agents cost tokens，glue is free」；六大 pattern（classify-and-act、fan-out-synthesize、adversarial verification、generate-filter、tournament、loop-until-done）+ 三大失敗模式（laziness/self-preferential bias/goal drift）。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>Orchestrator 移到 code 的核心洞察</strong>：workflow 之前，每個 routing 決策是一個付費 turn；現在是 plain code（loops + filters + sort）——agents 有 token 成本，glue 沒有</li><li><strong>三大失敗模式（引用 Anthropic 工程 blog）</strong>： <ul><li><strong>Laziness</strong>：叫 model 審查 50 項，它做 35 項就結束；code loop 跑到 list 為空</li><li><strong>Self-preferential bias</strong>：叫 model 評分自己的工作，分數偏高；harness 生成獨立 judge subagent（sometimes different model）+ majority 要求</li><li><strong>Goal drift</strong>：長 session 中「不要動 auth」在第 80 輪消失；目標在 script 中，不會 drift，因為不在被 squeeze 的 context 裡</li></ul></li><li><strong>六大 workflow pattern</strong>： <ul><li>Classify-and-act：一個 agent 決定類型，script 路由</li><li>Fan-out-synthesize：一個 agent per piece，code 合併</li><li>Adversarial verification：獨立 agent 對照 rubric 核查</li><li>Generate-filter：多候選 → 去重 → 保留最佳</li><li>Tournament：agents 多種方式嘗試 → judge 比較直到一勝</li><li>Loop-until-done：spawn until stop condition（實作+文件+測試一次完成）</li></ul></li><li><strong>subagent vs workflow 決策</strong>：一輪 parallel judgment → subagent；N 個 stage 互相依賴（stage N 輸出決定 stage N+1）→ workflow</li><li><strong>案例：100 份客戶訪談</strong>：Extract（cheap model per interview）→ Canonicalize（agent 聚類去重）→ Score（code，無 model）→ Generate+Triage → Build → Inspect+Rerun；122 candidates → 11 needs → 3 prototypes</li></ol><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li>文章指向作者的 The Product Compass newsletter（商業動機），但技術內容本身有獨立價值</li><li>六大 pattern 名稱引用自 Thariq+Sid（Anthropic）blog，作者有明確歸因</li><li>Score 那一步用 code（frequency × importance × (5-satisfaction)）而非 model 是關鍵成本控制點</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>理由</th></tr></thead><tbody><tr><td>A. Workspace 可行動性</td><td>7/10</td><td>六 pattern + 三失敗模式 + subagent vs workflow 決策 可直接使用</td></tr><tr><td>B. 創新性</td><td>6/10</td><td>主要是 Anthropic blog 的 PM 轉述；100 訪談案例和 Score=code 是好的具體示例</td></tr><tr><td>C. 證據品質</td><td>7/10</td><td>113 agents/1.95M tokens 個人實測；pattern 來源有歸因</td></tr><tr><td>D. 技術深度</td><td>6/10</td><td>六步 pipeline 有細節；但技術實作未深入（workflow JS 未展示）</td></tr><tr><td>E. 泛化性</td><td>8/10</td><td>六 pattern 適用任何 multi-agent orchestration；PM 框架額外增加應用面</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.80/10</strong></td><td>A×0.3 + B×0.2 + C×0.2 + D×0.15 + E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule<br><strong>整合位置</strong>：<code>subagent-strategy.md</code>：三失敗模式（laziness/self-preferential/goal-drift）+ 六 pattern 名稱索引；<code>core.md</code>：「orchestrator off model = goal drift prevention」<br><strong>整合狀態</strong>：待實作</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Anthropic just shipped dynamic workflows. I ran one: 113 agents, 1.95M tokens, 3 prototypes, in 12 minutes. The code that coordinated them spent zero. That zero is the upgrade.</p><p>I gave Claude a product-discovery job and one keyword: ultracode. It didn&#39;t answer me. It wrote a JavaScript, then used it to spin up a fleet of agents and point them at the work.</p><p>Twelve minutes later: 113 agents had read 100 synthetic customer interviews on 1.95M tokens. 622 raw opportunities, clustered to 11 needs, scored, then turned into 3 clickable prototypes, built and verified. The JavaScript that coordinated all of it spent zero model tokens. The model did the judgment. The code did the coordination.</p><p>The orchestrator moved off the model and into code.</p><h2 id="what-a-dynamic-workflow-is" tabindex="-1">What a dynamic workflow is <a class="header-anchor" href="#what-a-dynamic-workflow-is" aria-label="Permalink to &quot;What a dynamic workflow is&quot;">​</a></h2><p>A short JavaScript program Claude writes on the fly to coordinate subagents. You trigger it with ultracode, or by asking Claude to use a workflow.</p><p>Fan out N agents. The orchestrator is what decides what each one does, gathers the outputs, drops the repeats, and routes the survivors. Until now the orchestrator was the model. Every routing decision was a paid turn. Now it&#39;s plain code: loops, filters, a sort. The agents still cost tokens, because agents reason. The glue between them doesn&#39;t.</p><p><strong>Agents cost tokens. The glue is fast, free, and deterministic.</strong></p><h2 id="when-a-workflow-beats-a-subagent" tabindex="-1">When a workflow beats a subagent <a class="header-anchor" href="#when-a-workflow-beats-a-subagent" aria-label="Permalink to &quot;When a workflow beats a subagent&quot;">​</a></h2><p>A single fan-out and merge is a subagent job. A competitor teardown is the case: ten agents, one synthesis, no decisions in between.</p><p>A workflow earns its keep when stage N&#39;s output decides stage N+1. Route, then score. Score, then filter. Generate, then verify, then build.</p><p>Mental model:</p><ul><li>Use a subagent when the job is one round of parallel judgment.</li><li>Use a workflow when the steps talk to each other.</li></ul><h2 id="why-move-the-orchestrator-off-the-model" tabindex="-1">Why move the orchestrator off the model <a class="header-anchor" href="#why-move-the-orchestrator-off-the-model" aria-label="Permalink to &quot;Why move the orchestrator off the model&quot;">​</a></h2><p>Long jobs the model runs itself fail three predictable ways, all because the model is holding the plan:</p><ul><li><strong>Laziness</strong>: Ask it to review 50 items, it does 35 and calls it done. A loop runs until the list is empty. A loop doesn&#39;t get tired.</li><li><strong>Self-preferential bias</strong>: Ask it to grade its own work, it grades generously. The harness spawns a separate judge in its own context, sometimes a different model, and requires a majority. The grader is no longer the thing being graded.</li><li><strong>Goal drift</strong>: Over a long session &quot;don&#39;t touch auth&quot; can evaporate by turn 80. When the goal lives in the script it can&#39;t drift, because the script isn&#39;t in the context getting squeezed.</li></ul><h2 id="the-six-patterns" tabindex="-1">The six patterns <a class="header-anchor" href="#the-six-patterns" aria-label="Permalink to &quot;The six patterns&quot;">​</a></h2><p>Once the orchestrator is code, six shapes recur:</p><ol><li><strong>Classify-and-act</strong>: one agent decides the type, the script routes it. Example: bug vs feature vs noise.</li><li><strong>Fan-out-and-synthesize</strong>: one agent per piece, merged in code. Examples: market research, competitor teardown.</li><li><strong>Adversarial verification</strong>: a separate agent checks the output against a rubric. Example: fact-checking a PRD against the sources.</li><li><strong>Generate-and-filter</strong>: many candidates, deduped, the survivors kept. Examples: naming, positioning, ideation.</li><li><strong>Tournament (compare)</strong>: agents attempt the task different ways, judges compare until one wins. Example: product strategy.</li><li><strong>Loop-until-done</strong>: spawn until a stop condition. Example: implement, document, and test a feature in one shot.</li></ol><h2 id="a-worked-example-100-interviews" tabindex="-1">A worked example: 100 interviews <a class="header-anchor" href="#a-worked-example-100-interviews" aria-label="Permalink to &quot;A worked example: 100 interviews&quot;">​</a></h2><p>Six stages, each feeding the next:</p><ul><li><strong>Extract</strong> → one cheap-model agent per interview; each returns structured opportunities, the persona, and verbatims. Bounded, repetitive: Haiku or Sonnet, not Opus.</li><li><strong>Canonicalize</strong> → one agent clusters the raw opportunities into a canonical set. The same need arrives under a dozen names; merging synonyms is judgment, so it&#39;s a model, not code.</li><li><strong>Score (code, no model)</strong> → rank each canonical opportunity by frequency × importance × (5 − satisfaction).</li><li><strong>Generate and triage</strong> → for the top opportunities, an agent proposes solution ideas; a separate judge ranks them by ROI and keeps the top 3 to build.</li><li><strong>Build</strong> → an agent uses the frontend-design skill to write a clickable HTML prototype.</li><li><strong>Inspect and rerun</strong> → a smoke check reruns any prototype that fails to render or any extraction that came back low-confidence. This is the real loop: one stage&#39;s output decides whether an earlier stage runs again.</li></ul><p>113 agents, 1.95M tokens, 12.5 minutes. 3 of 3 prototypes built and verified. The JavaScript that routed, scored, gated, and looped spent zero.</p><p>Next time you want Claude to process 100 messy inputs, don&#39;t ask it to try harder. Give it the goal and let it write the harness.</p><p>Pattern names and failure-mode framing from &quot;A harness for every task: dynamic workflows in Claude Code&quot; by @trq212 and @sidbid (Anthropic). The firsthand run and the PM translation are mine.</p>',40)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
